if set(_MESSAGES) != set(LANGUAGES):
    raise RuntimeError("Schedule wizard onboarding must cover every supported language.")
if any(set(catalog) != {"intro", "continue"} for catalog in _MESSAGES.values()):
    raise RuntimeError("Schedule wizard onboarding translations are incomplete.")


def translate_schedule_wizard(language: str | None, key: str) -> str:
    locale = normalize_language(language)
    return _MESSAGES.get(locale, _MESSAGES[DEFAULT_LANGUAGE]).get(
        key, _MESSAGES[DEFAULT_LANGUAGE].get(key, key)
    )
